CREATE OR REPLACE FUNCTION create_user_agent(character varying) RETURNS integer
    LANGUAGE plpgsql STRICT
    AS $_$
DECLARE ua_id INT;
BEGIN
  LOOP
    SELECT id INTO ua_id FROM user_agents WHERE name = $1 FOR KEY SHARE;
    IF FOUND THEN
      RETURN ua_id;
    END IF;

    INSERT INTO user_agents (name) VALUES ($1)
      ON CONFLICT (name) DO NOTHING
      RETURNING id INTO ua_id;

    IF FOUND THEN
      RETURN ua_id;
    END IF;
  END LOOP;
END;
$_$;
